function SettingsTab({currentTheme, customColor, onSelectCustom, dark, onToggleDark, onDeleteAccount}){
  const [hexInput, setHexInput] = useState(customColor);
  useEffect(()=>{ setHexInput(customColor); }, [customColor]);

  const applyHexInput = () => {
    const h = hexInput.trim();
    if (isValidHexColor(h)) onSelectCustom(h.length===4
      ? "#"+h.slice(1).split("").map(c=>c+c).join("")
      : h);
  };

  return(
    <div style={{maxWidth:680,margin:"0 auto"}}>
      <div className="coc-card" style={{padding:"22px 20px"}}>
        <div className="coc-folder-tab">SETTINGS</div>
        <div className="coc-display" style={{fontSize:16.5,color:"var(--accent-deep)",marginBottom:18}}>설정</div>

        <div className="coc-label" style={{marginBottom:6}}>테마 색상</div>
        <div style={{fontSize:12.5,color:"var(--text-faint)",marginBottom:12}}>원하는 색을 직접 골라보세요. 나머지 배경·테두리 색은 자동으로 맞춰져요.</div>
        <div style={{display:"flex",alignItems:"center",gap:10,flexWrap:"wrap"}}>
          <label style={{position:"relative",width:46,height:46,borderRadius:10,overflow:"hidden",border:"2px solid "+(currentTheme==="custom"?"var(--accent)":"var(--border)"),cursor:"pointer",flexShrink:0}}>
            <input type="color" value={customColor} onChange={e=>onSelectCustom(e.target.value)}
              style={{position:"absolute",top:-6,left:-6,width:60,height:60,border:"none",padding:0,cursor:"pointer"}}/>
          </label>
          <input className="coc-input coc-mono" value={hexInput}
            onChange={e=>setHexInput(e.target.value)}
            onBlur={applyHexInput}
            onKeyDown={e=>{if(e.key==="Enter"){e.preventDefault();applyHexInput();}}}
            placeholder="#3388ff" style={{maxWidth:130}}/>
          <button type="button" className="coc-btn ghost small" onClick={applyHexInput}>적용</button>
          {currentTheme==="custom"&&<span style={{fontSize:12.5,color:"var(--accent)",display:"inline-flex",alignItems:"center",gap:3}}><Check size={13}/> 적용 중</span>}
        </div>

        <div style={{height:1,background:"var(--border-soft)",margin:"20px 0 18px"}}/>

        <div className="coc-label" style={{marginBottom:6}}>화면 모드</div>
        <div style={{fontSize:12.5,color:"var(--text-faint)",marginBottom:12}}>고른 테마 색은 그대로 두고 배경만 어둡게 바꿔요. 이 기기에만 저장됩니다.</div>
        <div style={{display:"flex",gap:10,marginBottom:22,flexWrap:"wrap"}}>
          {[{v:false,label:"밝게",Icon:Sun},{v:true,label:"어둡게",Icon:Moon}].map(o=>(
            <button key={o.label} type="button" onClick={()=>onToggleDark(o.v)}
              style={{
                display:"flex",alignItems:"center",gap:8,padding:"10px 18px",
                borderRadius:10,border:"2px solid "+(dark===o.v?"var(--accent)":"var(--border)"),
                background:dark===o.v?"var(--bg-panel)":"var(--surface)",cursor:"pointer",transition:"all 0.15s",
              }}>
              <o.Icon size={15} color={dark===o.v?"var(--accent-deep)":"var(--text-dim)"}/>
              <span style={{fontSize:14.5,fontWeight:dark===o.v?700:400,color:dark===o.v?"var(--accent-deep)":"var(--text-dim)"}}>{o.label}</span>
              {dark===o.v&&<Check size={13} color="var(--accent)"/>}
            </button>
          ))}
        </div>

        <div style={{height:1,background:"var(--border-soft)",margin:"4px 0 18px"}}/>

        <div className="coc-label" style={{marginBottom:6,color:"#c05050"}}>회원 탈퇴</div>
        <div style={{fontSize:12.5,color:"var(--text-faint)",marginBottom:12}}>
          로그인 정보가 삭제되어 이 닉네임으로 다시 로그인할 수 없게 돼요. 그동안 만든 세션·캐릭터는
          다른 사람과 공유되어 있을 수 있어 그대로 남아있어요.
        </div>
        <button type="button" className="coc-btn ghost small" onClick={onDeleteAccount}
          style={{borderColor:"#c05050",color:"#c05050"}}>
          회원 탈퇴
        </button>
      </div>
    </div>
  );
}

/* ============================== MY PAGE ============================== */

function MyPage({userCode,profile,setProfile}){
  const [local,setLocal]=useState(profile);
  const [saving,setSaving]=useState(false);
  const [saved,setSaved]=useState(false);
  const [charList,setCharList]=useState([]);
  const [roomMap,setRoomMap]=useState({});
  const [loadingChars,setLoadingChars]=useState(true);
  const [viewing,setViewing]=useState(null);
  const [viewDraft,setViewDraft]=useState(null);
  const [savingChar,setSavingChar]=useState(false);

  useEffect(()=>setLocal(profile),[profile]);

  useEffect(()=>{
    const unsub=storeListenPrefix("char:",list=>{
      setCharList(list.map(x=>x.value));setLoadingChars(false);
    });
    return()=>unsub();
  },[]);
  useEffect(()=>{
    const unsub=storeListenPrefix("room:",list=>{
      const map={};list.forEach(x=>{map[x.value.id]=x.value;});
      setRoomMap(map);
    });
    return()=>unsub();
  },[]);

  const myChars=charList.filter(c=>c.ownerCode===userCode)
    .map(c=>({...c,__room:roomMap[c.roomId]}))
    .sort((a,b)=>(b.createdAt||0)-(a.createdAt||0));

  const save=async()=>{
    setSaving(true);
    const res=await storeSet(`profile:${userCode}`,local,true);
    setSaving(false);
    if(res.ok){setProfile(local);setSaved(true);setTimeout(()=>setSaved(false),1600);}
    else alert(`프로필 저장 실패: ${res.error}`);
  };

  // 캐릭터 카드를 누르면 곧바로 수정 가능한 시트가 열립니다(별도 "수정" 버튼 없이,
  // 사진 변경 포함 모든 항목을 바로 고칠 수 있어요). "저장"을 누르면 반영됩니다.
  const openChar=c=>{ setViewing(c); setViewDraft(c); };
  const closeChar=()=>{ setViewing(null); setViewDraft(null); };
  const saveChar=async()=>{
    if(!viewDraft?.id||!viewDraft?.roomId)return;
    setSavingChar(true);
    const res=await storeSet(`char:${viewDraft.roomId}:${viewDraft.id}`,viewDraft,true);
    setSavingChar(false);
    if(res.ok) closeChar();
    else alert(`저장 실패: ${res.error}`);
  };

  return(
    <div style={{maxWidth:680,margin:"0 auto"}}>
      <div className="coc-card" style={{padding:"20px",marginBottom:20}}>
        <div className="coc-folder-tab">PROFILE · {userCode}</div>
        <div className="coc-display" style={{fontSize:16.5,color:"var(--accent-deep)",marginBottom:14}}>마이페이지</div>
        <div className="coc-label" style={{marginBottom:5}}>표시 이름</div>
        <input className="coc-input" value={local.name} onChange={e=>setLocal({...local,name:e.target.value})} style={{marginBottom:14,maxWidth:260}}/>
        <div className="coc-label" style={{marginBottom:5}}>사진</div>
        <AvatarUpload value={local.avatar} onChange={v=>setLocal({...local,avatar:v})}/>
        <div style={{display:"flex",justifyContent:"flex-end",alignItems:"center",gap:10,marginTop:16}}>
          {saved&&<span style={{color:"var(--accent)",fontSize:13}}>저장됨</span>}
          <button className="coc-btn" onClick={save} disabled={saving}>{saving?"저장 중...":"저장"}</button>
        </div>
      </div>
      <div className="coc-label" style={{marginBottom:10}}>내 캐릭터 모음</div>
      {loadingChars?(
        <div style={{color:"var(--text-faint)",fontSize:14,padding:20,textAlign:"center"}}>불러오는 중...</div>
      ):myChars.length===0?(
        <div className="coc-card" style={{padding:32,textAlign:"center"}}>
          <div style={{color:"var(--text-faint)",fontSize:14}}>아직 만든 캐릭터가 없어요. 세션방에 들어가서 첫 탐사자를 만들어보세요!</div>
        </div>
      ):(
        <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(148px,1fr))",gap:10}}>
          {myChars.map(c=>(
            <div key={c.id} className="coc-card" style={{padding:14,cursor:"pointer",textAlign:"center",position:"relative"}} onClick={()=>openChar(c)}>
              <button type="button" title="캐릭터 삭제"
                onClick={async e=>{
                  e.stopPropagation();
                  if(!window.confirm(`"${c.name||"이름 없음"}" 캐릭터를 삭제할까요? 되돌릴 수 없어요.`))return;
                  await storeDelete(`char:${c.roomId}:${c.id}`,true);
                }}
                style={{position:"absolute",top:6,right:6,width:22,height:22,borderRadius:6,border:"1px solid var(--border)",
                  background:"var(--surface)",color:"var(--text-faint)",cursor:"pointer",display:"flex",
                  alignItems:"center",justifyContent:"center",padding:0}}>
                <Trash2 size={12}/>
              </button>
              <div style={{width:50,height:50,borderRadius:"50%",overflow:"hidden",background:"var(--bg-panel)",margin:"0 auto 8px",border:"1px solid var(--border)"}}>
                {c.avatar?<img src={c.avatar} style={{width:"100%",height:"100%"}} className="coc-avatar"/>:<Sparkles size={20} color="var(--accent-soft)" style={{margin:15}}/>}
              </div>
              <div style={{fontSize:14.5,fontWeight:600}}>{c.name}</div>
              <div className="coc-mono" style={{fontSize:11.5,color:"var(--text-faint)",marginTop:3}}>{c.__room?.title||"알 수 없는 세션"}</div>
            </div>
          ))}
        </div>
      )}
      {viewing&&(
        <div className="coc-modal-backdrop" onClick={closeChar}>
          <div className="coc-modal" onClick={e=>e.stopPropagation()}>
            <div style={{padding:20}}>
              <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:4}}>
                <div className="coc-display" style={{fontSize:15,color:"var(--accent-deep)"}}>탐사자 시트</div>
                <button className="coc-btn ghost small" onClick={closeChar} style={{padding:6}}><X size={13}/></button>
              </div>
              <SheetEditor sheet={viewDraft} setSheet={setViewDraft} allowRoll={true}/>
              <button className="coc-btn" style={{width:"100%",justifyContent:"center",marginTop:14}} disabled={savingChar} onClick={saveChar}>
                {savingChar?"저장 중...":"저장"}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

/* ============================== ROOMS ============================== */

function JoinRoomModal({onClose,onJoined,userCode}){
  const [code,setCode]=useState("");
  const [error,setError]=useState("");
  const [joining,setJoining]=useState(false);

  const submit=async()=>{
    const c=code.trim().toUpperCase();
    if(!c){ setError("초대 코드를 입력해 주세요."); return; }
    setJoining(true); setError("");
    try{
      const roomId=await storeGet(`invite:${c}`,true);
      if(!roomId){ setError("유효하지 않은 초대 코드입니다."); setJoining(false); return; }
      const room=await storeGet(`room:${roomId}`,true);
      if(!room){ setError("존재하지 않는 세션입니다."); setJoining(false); return; }
      const members=room.members||[room.creatorCode];
      if(!members.includes(userCode)){
        const updated={...room,members:[...members,userCode]};
        const res=await storeSet(`room:${room.id}`,updated,true);
        if(!res.ok){ setError(`참가 실패: ${res.error}`); setJoining(false); return; }
      }
      setJoining(false);
      onJoined();
    }catch(err){
      setError(`오류가 발생했습니다: ${err?.message||String(err)}`);
      setJoining(false);
    }
  };

  return(
    <div className="coc-modal-backdrop" onClick={onClose}>
      <div className="coc-modal" style={{maxWidth:360}} onClick={e=>e.stopPropagation()}>
        <div style={{padding:20}}>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:16}}>
            <div className="coc-display" style={{fontSize:16,color:"var(--accent-deep)"}}>방 참가</div>
            <button className="coc-btn ghost small" onClick={onClose} style={{padding:6}}><X size={13}/></button>
          </div>
          <div className="coc-label" style={{marginBottom:5}}>초대 코드</div>
          <input className="coc-input coc-mono" value={code}
            onChange={e=>{setCode(e.target.value.toUpperCase().slice(0,6));setError("");}}
            onKeyDown={e=>{if(e.key==="Enter"){e.preventDefault();submit();}}}
            placeholder="XXXXXX" style={{textAlign:"center",fontSize:20.5,letterSpacing:"0.25em",marginBottom:14}} autoFocus/>
          {error&&<div style={{color:"var(--accent)",fontSize:13,marginBottom:12}}>{error}</div>}
          <button className="coc-btn" style={{width:"100%",justifyContent:"center",padding:11}} disabled={!code.trim()||joining} onClick={submit}>
            {joining?"참가하는 중...":"참가하기"}
          </button>
        </div>
      </div>
    </div>
  );
}

function RoomsTab({userCode,onEnterRoom,theme}){
  const [allRooms,setAllRooms]=useState([]);
  const [loading,setLoading]=useState(true);
  const [showCreate,setShowCreate]=useState(false);
  const [showJoin,setShowJoin]=useState(false);
  const [editing,setEditing]=useState(null);
  const [exportingRoom,setExportingRoom]=useState(null);

  useEffect(()=>{
    const unsub=storeListenPrefix("room:",list=>{
      const sorted=list.map(x=>x.value).sort((a,b)=>(b.createdAt||0)-(a.createdAt||0));
      setAllRooms(sorted);setLoading(false);
    });
    return()=>unsub();
  },[]);

  // 로비에는 "내가 참가한 방"만 노출됩니다. (기존에 members 필드가 없던 방은
  // 하위 호환을 위해 방을 만든 사람에게만 보이는 것으로 취급합니다.)
  const rooms=allRooms.filter(r=>(r.members||[r.creatorCode]).includes(userCode));

  return(
    <div style={{maxWidth:680,margin:"0 auto"}}>
      <div style={{display:"flex",justifyContent:"flex-end",alignItems:"center",marginBottom:16}}>
        <div style={{display:"flex",gap:8}}>
          <button className="coc-btn ghost" onClick={()=>setShowJoin(true)}>방 참가</button>
          <button className="coc-btn" onClick={()=>setShowCreate(true)}><Plus size={13}/> 새 게임</button>
        </div>
      </div>
      {loading?(
        <div style={{color:"var(--text-faint)",fontSize:14,padding:22,textAlign:"center"}}>불러오는 중...</div>
      ):rooms.length===0?(
        <div className="coc-card" style={{padding:36,textAlign:"center"}}>
          <div style={{color:"var(--text-dim)",fontSize:14.5,marginBottom:5}}>참가 중인 세션이 없습니다.</div>
          <div style={{color:"var(--text-faint)",fontSize:13}}>새 게임으로 만들거나, 초대 코드를 받았다면 방 참가를 눌러보세요.</div>
        </div>
      ):(
        <div style={{display:"grid",gap:10}}>
          {rooms.map((r,i)=>{
            const isMyRoom=r.creatorCode===userCode;
            return(
              <div key={r.id} className="coc-card" style={{padding:"16px 18px",cursor:"pointer",display:"flex",justifyContent:"space-between",alignItems:"center"}}
                onClick={()=>onEnterRoom(r)}>
                <div className="coc-folder-tab">No.{String(rooms.length-i).padStart(3,"0")}{isMyRoom&&" · GM"}</div>
                <div style={{display:"flex",alignItems:"center",gap:8}}>
                  <div>
                    <div className="coc-display" style={{fontSize:15.5,color:"var(--text)"}}>{r.title}</div>
                    <div className="coc-mono" style={{fontSize:12,color:"var(--text-faint)",marginTop:4}}>{fmtDate(r.date)}</div>
                  </div>
                </div>
                <div style={{display:"flex",gap:6,alignItems:"center"}}>
                  <button className="coc-btn ghost small" onClick={e=>{e.stopPropagation();setExportingRoom(r);}}>내보내기</button>
                  {isMyRoom&&(
                    <button className="coc-btn ghost small" onClick={e=>{e.stopPropagation();setEditing(r);}}><Settings size={11}/></button>
                  )}
                  <ArrowLeft size={14} color="var(--text-faint)" style={{transform:"rotate(180deg)"}}/>
                </div>
              </div>
            );
          })}
        </div>
      )}
      {showCreate&&<RoomModal onClose={()=>setShowCreate(false)} onSaved={()=>setShowCreate(false)} userCode={userCode}/>}
      {showJoin&&<JoinRoomModal onClose={()=>setShowJoin(false)} onJoined={()=>setShowJoin(false)} userCode={userCode}/>}
      {editing&&<RoomModal room={editing} onClose={()=>setEditing(null)}
        onSaved={()=>setEditing(null)}
        onDeleted={()=>setEditing(null)}
        userCode={userCode}/>}
      {exportingRoom&&<ExportModal room={exportingRoom} theme={theme} onClose={()=>setExportingRoom(null)}/>}
    </div>
  );
}

/* ============================== 세션 백업(내보내기) ============================== */
// 끝난 세션방을 지우기 전에 채팅 기록을 HTML/TXT 파일로 저장해두는 기능입니다.
// (한 번 읽어서 파일로 저장하는 일회성 조회라 평소 읽기 비용에는 영향이 없어요.)

function safeFileName(s){
  return (s||"session").replace(/[\\/:*?"<>|]/g,"_").trim().slice(0,60) || "session";
}
function escapeHtmlExport(s){
  return String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;");
}
function styleObjToCss(obj){
  return Object.entries(obj).map(([k,v])=>k.replace(/[A-Z]/g,c=>"-"+c.toLowerCase())+":"+v).join(";");
}
// 채팅 본문의 **굵게** *기울임* __밑줄__ ~~취소선~~ / <span style="..."> 서식을 실제 HTML 태그로 변환.
// theme을 넘기면, 메시지 안에 박혀있는 var(--accent-deep)/var(--accent)(=지금 보는 사람의 테마색을
// 그대로 따라가는 값)을 그 사람의 실제 색상값으로 바꿔서 내보냅니다. 이 값들은 앱 안에서만
// 뜻이 통하는 값이라, 내보낸 파일 단독으로는 해석이 안 되기 때문입니다.
// 강조 색상이었던 부분은 data-role="accent"로 표시해서, 나중에 색상 커스터마이즈 도구가
// 정확히 찾아서 바꿔줄 수 있게 해둡니다.
function chatTextToHtml(text,theme){
  const re=/<span style="([^"<>]*)">(.*?)<\/span>|\*\*(.+?)\*\*|\*(.+?)\*|~~(.+?)~~|__(.+?)__/g;
  let out="",last=0,m;
  while((m=re.exec(text))!==null){
    if(m.index>last) out+=escapeHtmlExport(text.slice(last,m.index));
    if(m[1]!==undefined){
      let styleStr=m[1];
      const isAccent=/var\(\s*--accent(-deep)?\s*\)/.test(styleStr);
      if(theme&&isAccent){
        styleStr=styleStr
          .replace(/var\(\s*--accent-deep\s*\)/g,theme.accentDeep)
          .replace(/var\(\s*--accent\s*\)/g,theme.accent);
      }
      const roleAttr=isAccent?' data-role="accent"':"";
      out+=`<span style="${styleObjToCss(parseInlineStyle(styleStr))}"${roleAttr}>${escapeHtmlExport(m[2])}</span>`;
    }
    else if(m[3]!==undefined) out+=`<strong>${escapeHtmlExport(m[3])}</strong>`;
    else if(m[4]!==undefined) out+=`<em>${escapeHtmlExport(m[4])}</em>`;
    else if(m[5]!==undefined) out+=`<s>${escapeHtmlExport(m[5])}</s>`;
    else if(m[6]!==undefined) out+=`<u>${escapeHtmlExport(m[6])}</u>`;
    last=m.index+m[0].length;
  }
  if(last<text.length) out+=escapeHtmlExport(text.slice(last));
  return out.replace(/\n/g,"<br>");
}
async function fetchRoomTranscript(room){
  const [msgEntries,tabsData]=await Promise.all([
    storeListValues(`chat:${room.id}:`,true),
    storeGet(`tabs:${room.id}`,true),
  ]);
  const tabs=(tabsData&&Array.isArray(tabsData)&&tabsData.length)?tabsData:[{id:"main",label:"메인"}];
  const labelOf={};tabs.forEach(t=>labelOf[t.id]=t.label);
  const byTab={};
  msgEntries.forEach(({value:m})=>{
    const tid=m.tabId||"main";
    (byTab[tid]=byTab[tid]||[]).push(m);
  });
  const ids=tabs.map(t=>t.id).filter(id=>byTab[id]);
  Object.keys(byTab).forEach(id=>{if(!ids.includes(id))ids.push(id);});
  return ids.map(id=>({id,label:labelOf[id]||id,messages:(byTab[id]||[]).sort((a,b)=>a.timestamp-b.timestamp)}));
}

function buildHtmlExport(room,transcript,theme){
  // 티스토리 등 블로그 에디터는 붙여넣을 때 <style> 태그를 걸러내는 경우가 많아서,
  // class + 스타일시트 방식 대신 태그 하나하나에 style을 직접 박아넣는 방식으로
  // 만들었습니다. 이렇게 하면 <style> 블록이 통째로 사라져도 디자인이 유지됩니다.
  // 이름·선택지도 테마색 대신 블로그 스킨의 기본 글자색(inherit)을 그대로 따라갑니다.
  const S={
    line:"display:flex;gap:9px;align-items:flex-start;padding:5px 0;font-size:inherit;font-family:'Noto Sans KR',sans-serif;color:inherit;",
    anon:"text-align:center;color:inherit;padding:10px 0;font-size:inherit;font-family:'Noto Sans KR',sans-serif;",
    name:"color:inherit;font-weight:600;",
    nameDim:"color:inherit;opacity:0.65;",
    mono:"font-family:monospace;font-size:0.83em;color:inherit;opacity:0.55;",
    ooc:"border:1px solid #cfe8f7;border-radius:3px;padding:0 4px;font-family:monospace;font-size:0.83em;color:inherit;opacity:0.55;",
    img:"max-width:320px;border-radius:8px;margin:0 auto;display:block;",
    avatarImg:"width:26px;height:26px;border-radius:50%;object-fit:cover;flex-shrink:0;margin-top:2px;",
    avatarPlaceholder:"width:26px;height:26px;border-radius:50%;background:#eef2f5;flex-shrink:0;margin-top:2px;",
    empty:"color:inherit;opacity:0.55;font-size:0.97em;padding:10px 0;font-family:'Noto Sans KR',sans-serif;",
    choice:"display:inline-block;border:1.5px solid currentColor;border-radius:999px;padding:5px 13px;margin:2px 4px;font-size:0.87em;font-weight:600;color:inherit;font-family:'Noto Sans KR',sans-serif;",
    choicePicked:"display:inline-block;border:1.5px solid currentColor;border-radius:999px;padding:5px 13px;margin:2px 4px;font-size:0.87em;color:inherit;opacity:0.55;text-decoration:line-through;font-family:'Noto Sans KR',sans-serif;",
  };
  const avatarHtml=g=>g.avatar
    ? `<img src="${g.avatar}" style="${S.avatarImg}">`
    : `<div style="${S.avatarPlaceholder}"></div>`;
  const tabsHtml=transcript.map(tab=>{
    // 같은 사람이 60초 안에 연달아 보낸 메시지는(선택지·판정 제외) 하나의 묶음으로 처리해서,
    // 프로필 사진·이름을 매 줄마다 반복하지 않고 묶음당 한 번만 넣습니다.
    // (예전에는 메시지 하나하나마다 사진 base64 코드가 통째로 반복돼서 파일이 쓸데없이 길었어요.)
    const groups=groupMessages(tab.messages);
    const msgs=groups.map(g=>{
      if(g.speaker==="narrate"||g.speaker==="system"||g.speaker==="choicepick"){
        return g.lines.map(line=>`<div style="${S.anon}" data-role="narrate">${chatTextToHtml(line,theme)}</div>`).join("\n");
      }
      if(g.speaker==="judge"){
        return `<div style="${S.anon}" data-role="judge">${chatTextToHtml(g.lines[0],theme)}</div>`;
      }
      if(g.speaker==="choice"){
        let d=null;try{d=JSON.parse(g.lines[0]);}catch{}
        if(!d) return `<div style="${S.anon}">(선택지)</div>`;
        const opts=d.options.map(opt=>{
          const picked=d.picked?.[opt];
          return picked
            ? `<span style="${S.choicePicked}" data-role="choice-picked">${escapeHtmlExport(opt)}</span>`
            : `<span style="${S.choice}" data-role="choice">${escapeHtmlExport(opt)}</span>`;
        }).join(" ");
        return `<div style="${S.anon}">${opts}</div>`;
      }
      if(g.speaker==="dice"){
        const bodies=g.lines.map(line=>{
          let d=null;try{d=JSON.parse(line);}catch{}
          return d?`<div>🎲 ${escapeHtmlExport(d.skillName)} <span style="${S.mono}">/${d.value}</span> → <b>${d.roll}</b> → <span style="color:${d.color}">${escapeHtmlExport(d.label)}</span></div>`:`<div>${escapeHtmlExport(line)}</div>`;
        }).join("");
        return `<div style="${S.line}">${avatarHtml(g)}<div><span style="${S.name}" data-role="char-name">${escapeHtmlExport(g.characterName||"")}</span> <span data-role="dialogue">${bodies}</span></div></div>`;
      }
      if(g.speaker==="image"){
        return g.lines.map(line=>`<div style="${S.anon}"><img src="${line}" style="${S.img}"></div>`).join("\n");
      }
      const myNameColor=safeNameColor(g.nameColor);
      const nameStyle=(g.speaker==="ooc"?S.nameDim:S.name)+(myNameColor?`color:${myNameColor};`:"");
      const suffix=g.speaker==="ooc"?` <span style="${S.ooc}">OOC</span>`:"";
      const linesHtml=g.lines.map(line=>`<div data-role="dialogue">${chatTextToHtml(line,theme)}</div>`).join("");
      return `<div style="${S.line}">${avatarHtml(g)}<div><span style="${nameStyle}" data-role="char-name">${escapeHtmlExport(g.characterName||"")}</span>${suffix}${linesHtml}</div></div>`;
    }).join("\n");
    return `<section>${msgs||`<div style="${S.empty}">기록 없음</div>`}</section>`;
  }).join("\n");

  return `<!DOCTYPE html><html lang="ko"><head><meta charset="UTF-8">
<title>${escapeHtmlExport(room.title)} — 세션 기록</title>
</head><body>
<div data-role="session-root" style="font-family:'Noto Sans KR',sans-serif;max-width:760px;margin:0 auto;padding:32px 20px 60px;line-height:1.7;">
${tabsHtml}
</div>
</body></html>`;
}

function downloadFile(filename,content,mime){
  const blob=new Blob([content],{type:mime});
  const url=URL.createObjectURL(blob);
  const a=document.createElement("a");
  a.href=url;a.download=filename;
  document.body.appendChild(a);a.click();document.body.removeChild(a);
  setTimeout(()=>URL.revokeObjectURL(url),2000);
}
// 파일로 저장하지 않고, 새 탭에서 바로 열어서 볼 수 있게 합니다.
function openInNewTab(content,mime){
  const blob=new Blob([content],{type:mime});
  const url=URL.createObjectURL(blob);
  window.open(url,"_blank");
  setTimeout(()=>URL.revokeObjectURL(url),60000);
}

// GM뿐 아니라 참가자 누구나 자기 방 채팅 기록을 HTML로 내보낼 수 있는 간단한 모달
function ExportModal({room,theme,onClose}){
  const [exporting,setExporting]=useState(false);
  const doExport=async()=>{
    setExporting(true);
    try{
      const transcript=await fetchRoomTranscript(room);
      const base=safeFileName(room.title)+"_"+(room.date||"session");
      downloadFile(base+".html", buildHtmlExport(room,transcript,theme), "text/html;charset=utf-8");
    }catch(err){
      alert("내보내기에 실패했습니다: "+(err?.message||String(err)));
    }
    setExporting(false);
  };
  return(
    <div className="coc-modal-backdrop" onClick={onClose}>
      <div className="coc-modal" style={{maxWidth:400}} onClick={e=>e.stopPropagation()}>
        <div style={{padding:20}}>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:12}}>
            <div className="coc-display" style={{fontSize:15,color:"var(--accent-deep)"}}>채팅 기록 내보내기</div>
            <button className="coc-btn ghost small" onClick={onClose} style={{padding:5}}><X size={12}/></button>
          </div>
          <div style={{fontSize:12.5,color:"var(--text-faint)",marginBottom:14}}>"{room.title}"의 채팅 기록을 HTML 파일로 저장해요. 티스토리 등 다른 곳에 붙여넣어 백업할 수 있어요.</div>
          <button className="coc-btn" style={{width:"100%",justifyContent:"center",padding:11}} onClick={doExport} disabled={exporting}>
            {exporting?"내보내는 중...":"HTML로 내보내기"}
          </button>
        </div>
      </div>
    </div>
  );
}

function RoomModal({room,onClose,onSaved,onDeleted,userCode}){
  const isEdit=!!room;
  const [title,setTitle]=useState(room?.title||"");
  const [date,setDate]=useState(room?.date||todayLocalISO());
  const [saving,setSaving]=useState(false);
  const [deleting,setDeleting]=useState(false);
  const [confirmDelete,setConfirmDelete]=useState(false);
  const [error,setError]=useState("");
  const [regenerating,setRegenerating]=useState(false);
  const [copied,setCopied]=useState(false);


  const submit=async()=>{
    const t=title.trim();if(!t)return;
    setSaving(true);setError("");
    const data=isEdit
      ?{...room,title:t,date}
      :{id:newId(),title:t,date,createdAt:Date.now(),creatorCode:userCode,inviteCode:genInviteCode(),members:[userCode]};
    const res=await storeSet(`room:${data.id}`,data,true);
    if(res.ok&&!isEdit){
      // 초대 코드 → 방 ID 역방향 조회용 문서
      await storeSet(`invite:${data.inviteCode}`,data.id,true);
    }
    setSaving(false);
    if(res.ok) onSaved(data);
    else setError(`저장에 실패했습니다.\n오류: ${res.error}`);
  };

  const regenerateCode=async()=>{
    setRegenerating(true);
    const newCode=genInviteCode();
    if(room.inviteCode) await storeDelete(`invite:${room.inviteCode}`,true);
    await storeSet(`invite:${newCode}`,room.id,true);
    const updated={...room,inviteCode:newCode};
    const res=await storeSet(`room:${room.id}`,updated,true);
    setRegenerating(false);
    if(res.ok) onSaved(updated);
  };

  const copyCode=()=>{
    if(!room?.inviteCode) return;
    navigator.clipboard?.writeText(room.inviteCode).then(()=>{setCopied(true);setTimeout(()=>setCopied(false),1600);});
  };

  const handleDelete=async()=>{
    if(!confirmDelete){setConfirmDelete(true);return;}
    setDeleting(true);
    await storeDelete(`room:${room.id}`,true);
    if(room.inviteCode) await storeDelete(`invite:${room.inviteCode}`,true);
    const chatKeys=await storeListKeys(`chat:${room.id}:`,true).catch(()=>({keys:[]}));
    const charKeys=await storeListKeys(`char:${room.id}:`,true).catch(()=>({keys:[]}));
    for(const k of(chatKeys.keys||[])) await storeDelete(k,true);
    for(const k of(charKeys.keys||[])) await storeDelete(k,true);
    setDeleting(false);
    onDeleted?.(room.id);
  };

  return(
    <div className="coc-modal-backdrop" onClick={onClose}>
      <div className="coc-modal" style={{maxWidth:400}} onClick={e=>e.stopPropagation()}>
        <div style={{padding:20}}>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:16}}>
            <div className="coc-display" style={{fontSize:16,color:"var(--accent-deep)"}}>{isEdit?"세션 설정":"새 세션 만들기"}</div>
            <button className="coc-btn ghost small" onClick={onClose} style={{padding:6}}><X size={13}/></button>
          </div>
          <div className="coc-label" style={{marginBottom:5}}>세션 제목</div>
          <input className="coc-input" value={title} onChange={e=>setTitle(e.target.value)} placeholder="시나리오 제목을 입력하세요" style={{marginBottom:14}} autoFocus/>
          <div className="coc-label" style={{marginBottom:5}}>날짜</div>
          <input type="date" className="coc-input coc-mono" value={date} onChange={e=>setDate(e.target.value)} style={{marginBottom:18}}/>

          {isEdit&&(
            <div style={{marginBottom:18}}>
              <div className="coc-label" style={{marginBottom:5}}>초대 코드</div>
              <div style={{fontSize:12.5,color:"var(--text-faint)",marginBottom:8}}>이 코드를 플레이어에게 알려 주면 들어올 수 있어요.</div>
              <div style={{display:"flex",alignItems:"center",gap:8}}>
                <div className="coc-mono" style={{flex:1,textAlign:"center",fontSize:20.5,letterSpacing:"0.25em",padding:"9px 0",background:"var(--bg-panel)",border:"1px solid var(--border)",borderRadius:8,color:"var(--accent-deep)",fontWeight:700}}>
                  {room.inviteCode||"------"}
                </div>
                <button type="button" className="coc-btn ghost small" onClick={copyCode} disabled={!room.inviteCode}>{copied?"복사됨":"복사"}</button>
                <button type="button" className="coc-btn ghost small" onClick={regenerateCode} disabled={regenerating}>{regenerating?"발급 중...":"재발급"}</button>
              </div>
            </div>
          )}

          {error&&<div style={{color:"var(--accent)",fontSize:13,marginBottom:12,whiteSpace:"pre-wrap"}}>{error}</div>}
          <button className="coc-btn" style={{width:"100%",justifyContent:"center",padding:11,marginBottom:isEdit?10:0}} disabled={!title.trim()||saving} onClick={submit}>
            {saving?"저장 중...":<><Plus size={13}/>{isEdit?"수정 완료":"세션 만들기"}</>}
          </button>

          {isEdit&&(
            <>
              <div style={{height:1,background:"var(--border-soft)",margin:"4px 0 10px"}}/>
              {confirmDelete?(
                <div style={{background:"var(--bg-panel)",border:"1px solid var(--border)",borderRadius:8,padding:"12px 14px"}}>
                  <div style={{fontSize:14,color:"var(--accent-deep)",marginBottom:10,fontWeight:600}}>
                    정말 삭제하시겠습니까?<br/>
                    <span style={{fontWeight:400,fontSize:13,color:"var(--text-dim)"}}>채팅과 캐릭터 데이터도 모두 삭제됩니다.</span>
                  </div>
                  <div style={{display:"flex",gap:8}}>
                    <button className="coc-btn ghost small" style={{flex:1,justifyContent:"center"}} onClick={()=>setConfirmDelete(false)} disabled={deleting}>취소</button>
                    <button className="coc-btn small" style={{flex:1,justifyContent:"center"}} onClick={handleDelete} disabled={deleting}>
                      {deleting?"삭제 중...":"삭제 확인"}
                    </button>
                  </div>
                </div>
              ):(
                <button className="coc-btn ghost small" style={{width:"100%",justifyContent:"center",color:"var(--text-dim)"}} onClick={handleDelete}>
                  이 세션 삭제
                </button>
              )}
            </>
          )}
        </div>
      </div>
    </div>
  );
}

