// GM이 대상·종류(단기적/장기적)·이름·내용을 골라 광기를 부여하는 창. 핸드아웃 관리 창과
// 똑같은 패턴(별도로 뜨는 모달)이라, "배부" 탭 안에 인라인으로 있던 예전 방식 대신 이걸 씁니다.
function MadnessAssignModal({participantsList,presenceMap,userCode,onClose,onSend}){
  const [target,setTarget]=useState(null);
  const [term,setTerm]=useState("단기적");
  const [name,setName]=useState("");
  const [note,setNote]=useState("");
  return(
    <div className="coc-modal-backdrop" onClick={onClose}>
      <div className="coc-modal" onClick={e=>e.stopPropagation()}>
        <div style={{padding:20}}>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:14}}>
            <div className="coc-display" style={{fontSize:15,color:"var(--accent-deep)"}}>광기 부여</div>
            <button className="coc-btn ghost small" onClick={onClose} style={{padding:6}}><X size={13}/></button>
          </div>
          <div className="coc-label" style={{marginBottom:6}}>대상</div>
          <div style={{display:"flex",flexWrap:"wrap",gap:6,marginBottom:12}}>
            {participantsList.filter(c=>c!==userCode).map(code=>{
              const displayName=presenceMap[code]?.charName||code;
              const active=target===code;
              return(
                <button key={code} type="button" onClick={()=>setTarget(code)}
                  style={{fontSize:11.5,padding:"5px 12px",borderRadius:999,cursor:"pointer",
                    background:active?"var(--accent)":"var(--surface)",color:active?"#fff":"var(--text-dim)",
                    border:"1px solid "+(active?"var(--accent)":"var(--border)")}}>
                  {displayName}
                </button>
              );
            })}
          </div>
          <div className="coc-label" style={{marginBottom:6}}>종류</div>
          <div style={{display:"flex",gap:6,marginBottom:12}}>
            {["단기적","장기적"].map(t=>(
              <button key={t} type="button" onClick={()=>setTerm(t)}
                style={{flex:1,fontSize:12.5,padding:"7px 0",borderRadius:6,cursor:"pointer",
                  background:term===t?"var(--accent)":"var(--surface)",color:term===t?"#fff":"var(--text-dim)",
                  border:"1px solid "+(term===t?"var(--accent)":"var(--border)")}}>
                {t} 광기
              </button>
            ))}
          </div>
          <div className="coc-label" style={{marginBottom:6}}>광기 이름</div>
          <input className="coc-input" value={name} onChange={e=>setName(e.target.value)} placeholder="예: 실어증" style={{marginBottom:12}}/>
          <div className="coc-label" style={{marginBottom:6}}>내용</div>
          <textarea className="coc-input" value={note} onChange={e=>setNote(e.target.value)} placeholder="증상·행동 등을 적어주세요" rows={4} style={{marginBottom:16,resize:"vertical"}}/>
          <button type="button" className="coc-btn" style={{width:"100%",justifyContent:"center"}}
            disabled={!target||!name.trim()}
            onClick={()=>{onSend(target,{name:name.trim(),term,note});onClose();}}>
            전송
          </button>
        </div>
      </div>
    </div>
  );
}

function HandoutManagerModal({room,userCode,handouts,roomParticipants,onClose}){
  const [showCreate,setShowCreate]=useState(false);
  const [title,setTitle]=useState("");
  const [text,setText]=useState("");
  const [image,setImage]=useState("");
  const [saving,setSaving]=useState(false);
  const [assigning,setAssigning]=useState(null);
  const [selection,setSelection]=useState({});
  const imgRef=useRef(null);

  const createHandout=async()=>{
    const t=title.trim();if(!t)return;
    setSaving(true);
    const id=newId();
    const handout={id,roomId:room.id,title:t,text:text.trim(),image,creatorCode:userCode,createdAt:Date.now(),visibleTo:[]};
    await storeSet(`handout:${room.id}:${id}`,handout,true);
    setSaving(false);setShowCreate(false);setTitle("");setText("");setImage("");
  };
  const deleteHandout=async h=>{
    if(!window.confirm(`'${h.title}' 핸드아웃을 삭제하시겠습니까?`))return;
    await storeDelete(`handout:${room.id}:${h.id}`,true);
  };
  const openAssign=h=>{
    setAssigning(h);
    const sel={};(h.visibleTo||[]).forEach(c=>sel[c]=true);setSelection(sel);
  };
  const saveAssign=async()=>{
    const visibleTo=Object.entries(selection).filter(([,v])=>v).map(([c])=>c);
    await storeSet(`handout:${room.id}:${assigning.id}`,{...assigning,visibleTo},true);
    setAssigning(null);
  };

  return(
    <div className="coc-modal-backdrop" onClick={onClose}>
      <div className="coc-modal" onClick={e=>e.stopPropagation()}>
        <div style={{padding:20}}>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:16}}>
            <div className="coc-display" style={{fontSize:15,color:"var(--accent-deep)"}}>핸드아웃 관리</div>
            <button className="coc-btn ghost small" onClick={onClose} style={{padding:6}}><X size={13}/></button>
          </div>

          {assigning?(
            <div>
              <button className="coc-btn ghost small" onClick={()=>setAssigning(null)} style={{marginBottom:12}}><ArrowLeft size={12}/> 목록으로</button>
              <div className="coc-display" style={{fontSize:14,marginBottom:4}}>{assigning.title}</div>
              <div className="coc-label" style={{marginBottom:8}}>누구에게 보여줄까요?</div>
              {roomParticipants.length===0?(
                <div style={{fontSize:12,color:"var(--text-faint)",marginBottom:14}}>아직 캐릭터를 만든 참가자가 없어요.</div>
              ):(
                <div style={{display:"flex",flexDirection:"column",gap:8,marginBottom:16}}>
                  {roomParticipants.map(code=>(
                    <label key={code} style={{display:"flex",alignItems:"center",gap:8,fontSize:13.5,cursor:"pointer",padding:"8px 10px",background:"var(--bg-panel)",borderRadius:8}}>
                      <input type="checkbox" checked={!!selection[code]} onChange={e=>setSelection(s=>({...s,[code]:e.target.checked}))} style={{width:16,height:16,cursor:"pointer"}}/>
                      {code}
                    </label>
                  ))}
                </div>
              )}
              <button type="button" className="coc-btn" style={{width:"100%",justifyContent:"center",padding:11}} onClick={saveAssign}>전송</button>
            </div>
          ):showCreate?(
            <div>
              <button className="coc-btn ghost small" onClick={()=>setShowCreate(false)} style={{marginBottom:12}}><ArrowLeft size={12}/> 목록으로</button>
              <div className="coc-label" style={{marginBottom:5}}>제목</div>
              <input className="coc-input" value={title} onChange={e=>setTitle(e.target.value)} placeholder="예: 낡은 편지" style={{marginBottom:12}} autoFocus/>
              <div className="coc-label" style={{marginBottom:5}}>내용</div>
              <textarea className="coc-input" rows={5} value={text} onChange={e=>setText(e.target.value)} placeholder="플레이어에게 보여줄 글 내용" style={{marginBottom:12}}/>
              <div className="coc-label" style={{marginBottom:5}}>사진 (선택)</div>
              <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:16}}>
                {image&&<img src={image} style={{width:56,height:56,borderRadius:8,objectFit:"cover",border:"1px solid var(--border)"}}/>}
                <button type="button" className="coc-btn ghost small" onClick={()=>imgRef.current?.click()}><Camera size={12}/> 사진 첨부</button>
                {image&&<button type="button" className="coc-btn ghost small" onClick={()=>setImage("")}>제거</button>}
              </div>
              <input ref={imgRef} type="file" accept="image/*" style={{display:"none"}}
                onChange={async e=>{const f=e.target.files?.[0];if(!f)return;setImage(await fileToResizedDataURL(f,640));e.target.value="";}}/>
              <button type="button" className="coc-btn" style={{width:"100%",justifyContent:"center",padding:11}} disabled={!title.trim()||saving} onClick={createHandout}>
                {saving?"저장 중...":"핸드아웃 만들기"}
              </button>
            </div>
          ):(
            <div>
              <button type="button" className="coc-btn" style={{width:"100%",justifyContent:"center",padding:11,marginBottom:16}} onClick={()=>setShowCreate(true)}>
                <Plus size={13}/> 새 핸드아웃 추가
              </button>
              {handouts.length===0?(
                <div style={{color:"var(--text-faint)",fontSize:12.5,textAlign:"center",padding:24}}>아직 만든 핸드아웃이 없어요.</div>
              ):(
                <div style={{display:"flex",flexDirection:"column",gap:8}}>
                  {handouts.map(h=>(
                    <div key={h.id} className="coc-card" style={{padding:12,display:"flex",alignItems:"center",gap:10}}>
                      {h.image?<img src={h.image} style={{width:40,height:40,borderRadius:6,objectFit:"cover",flexShrink:0}}/>:
                        <div style={{width:40,height:40,borderRadius:6,background:"var(--bg-panel)",flexShrink:0}}/>}
                      <div style={{flex:1,minWidth:0}}>
                        <div style={{fontSize:13.5,fontWeight:600,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{h.title}</div>
                        <div className="coc-mono" style={{fontSize:10.5,color:"var(--text-faint)"}}>
                          {(h.visibleTo||[]).length>0?`공개 대상: ${h.visibleTo.join(", ")}`:"아직 공개 안 됨"}
                        </div>
                      </div>
                      <button type="button" className="coc-btn small" onClick={()=>openAssign(h)}>전송</button>
                      <button type="button" onClick={()=>deleteHandout(h)} style={{background:"none",border:"none",cursor:"pointer",color:"var(--text-faint)",padding:4}}><Trash2 size={13}/></button>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

